onClick:
{{
  (async () => {
    const storeSelection = appsmith.store.carton_selection || {};
    const data = Table_Achats.tableData || [];

    // 1. Vérification hybride (Mémoire Appsmith + Base de données)
    const pointees = data.filter(r => 
      r.Dans_Carton_En_Cours === true || storeSelection[r.ID_Ligne_Achat] === true
    );

    if (pointees.length === 0) {
      showAlert('Pointez au moins un article avec le bouton vert avant de lancer le déballage !', 'warning');
      return;
    }

    // 2. Réinitialisation du message du scan
    await storeValue('lastScanResult', null);

    // 3. Ouverture immédiate de la modale
    showModal('modal_scan_reception');

    // 4. Chargement des réservations en arrière-plan sans bloquer l'IHM
    Get_Reservations_Actives.run().catch(() => {});
  })()
}}

tooltip:
{{
  Table_Achats.tableData.some(r => r.Statut_Achat === 'COMMANDÉ' || r.Statut_Achat === 'REÇU PARTIEL')
    ? "📦 Lancer le déballage des articles pointés"
    : "📥 Exporter le Panier en CSV"
}}
